const original = { name: 'Alice', address: { city: 'Paris' } };

// 1. SHALLOW COPY (Nested object is shared!)
const shallow = { ...original };
shallow.address.city = 'London';
console.log(original.address.city); // 'London' (Original was mutated!)

// 2. DEEP COPY (Modern native way)
const deep = structuredClone(original);
deep.address.city = 'Tokyo';
console.log(original.address.city); // 'London' (Original is safe!)
